package bo.edu.uagrm.saludu.agenda.api;
import bo.edu.uagrm.saludu.agenda.application.AvailabilityException;import bo.edu.uagrm.saludu.identity.infrastructure.SessionPrincipal;import bo.edu.uagrm.saludu.shared.persistence.*;import com.fasterxml.jackson.databind.*;import java.io.*;import java.util.*;import org.apache.poi.xwpf.usermodel.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/medical/encounters") public class ClinicalWordExportController {private final JdbcTemplate j;private final DatabaseActorContext c;private final ObjectMapper m;public ClinicalWordExportController(JdbcTemplate j,DatabaseActorContext c,ObjectMapper m){this.j=j;this.c=c;this.m=m;}@GetMapping("/{id}/export.docx") @PreAuthorize("hasAnyRole('REVIEW_DOCTOR','SPECIALIST')") @Transactional(readOnly=true) public ResponseEntity<byte[]> export(@PathVariable UUID id,@RequestParam(required=false) String purpose,@AuthenticationPrincipal SessionPrincipal p){c.apply(new DatabaseActor(p.id(),Set.copyOf(p.roles())));try{JsonNode root=m.readTree(j.queryForObject("select salud_u.obtener_ficha_exportable(?)::text",String.class,id));JsonNode patient=root.path("patient"),e=root.path("encounter");try(XWPFDocument doc=new XWPFDocument();ByteArrayOutputStream out=new ByteArrayOutputStream()){title(doc,"CENTRO DE ESPECIALIDADES MÉDICAS");title(doc,"Facultad de Ciencias de la Salud Humana · UAGRM");title(doc,e.path("encounter_type").asText().equals("INITIAL")?"Historia clínica de revisión médica":"Historia clínica de especialidad");line(doc,"Paciente",patient.path("fullName").asText());line(doc,"Carnet",patient.path("carnet").asText());line(doc,"Registro",patient.path("registrationCode").asText());line(doc,"Motivo",e.path("chief_complaint").asText());line(doc,"Evaluación",e.path("assessment").asText());line(doc,"Indicaciones",e.path("instructions").asText());line(doc,"Seguimiento",e.path("follow_up_text").asText());line(doc,"Finalidad",purpose==null?"Consulta clínica autorizada":purpose);title(doc,"Documento clínico confidencial");doc.write(out);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=ficha-clinica-"+id+".docx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.wordprocessingml.document")).body(out.toByteArray());}}catch(Exception x){throw new AvailabilityException(404,"No tienes acceso clínico a esta ficha.");}}private static void title(XWPFDocument d,String s){XWPFParagraph p=d.createParagraph();p.setAlignment(ParagraphAlignment.CENTER);XWPFRun r=p.createRun();r.setBold(true);r.setText(s);}private static void line(XWPFDocument d,String k,String v){XWPFParagraph p=d.createParagraph();XWPFRun a=p.createRun();a.setBold(true);a.setText(k+": ");p.createRun().setText(v==null||v.isBlank()?"No registrado":v);}}
